        public void SetTime(float elapsedSeconds, bool reduceMotion)
        {
            Initialize();
            if (!HasRequiredBindings)
            {
                throw new MissingReferenceException(
                    "Gate 04 rev 11 controller bindings are incomplete.");
            }

            ElapsedSeconds = Mathf.Clamp(
                elapsedSeconds,
                0f,
                PackOpeningGate04R011Profile.TotalSeconds);
            ReduceMotion = reduceMotion;
            CurrentSample = profile.Evaluate(ElapsedSeconds, reduceMotion);
            ApplyPack(CurrentSample);
            ApplyCase(CurrentSample);
            ApplyImpact(CurrentSample);
            ApplyCamera(CurrentSample);
            if (
                ElapsedSeconds <= 0f
                && string.IsNullOrEmpty(sealedStateFingerprint)
            )
            {
                sealedStateFingerprint = BuildStateFingerprint();
            }
        }

        public bool ReboundToSealed()
        {
            SetTime(0f, false);
            StopSourceEffects();
            return string.Equals(
                BuildStateFingerprint(),
                sealedStateFingerprint,
                StringComparison.Ordinal);
        }

        public bool TryGetCaseViewportBounds(out Rect viewportBounds)
        {
            viewportBounds = default;
            if (
                captureCamera == null
                || caseRenderers == null
                || caseRenderers.Length == 0
            )
            {
                return false;
            }

            bool hasBounds = false;
            Bounds worldBounds = default;
            for (int index = 0; index < caseRenderers.Length; index++)
            {
                Renderer renderer = caseRenderers[index];
                if (renderer == null)
                {
                    continue;
                }
                if (!hasBounds)
                {
                    worldBounds = renderer.bounds;
                    hasBounds = true;
                }
                else
                {
                    worldBounds.Encapsulate(renderer.bounds);
                }
            }
            if (!hasBounds)
            {
                return false;
            }

            Vector3 center = worldBounds.center;
            Vector3 extents = worldBounds.extents;
            float minX = float.PositiveInfinity;
            float minY = float.PositiveInfinity;
            float maxX = float.NegativeInfinity;
            float maxY = float.NegativeInfinity;
            for (int x = -1; x <= 1; x += 2)
            {
                for (int y = -1; y <= 1; y += 2)
                {
                    for (int z = -1; z <= 1; z += 2)
                    {
                        Vector3 viewport = captureCamera.WorldToViewportPoint(
                            center + Vector3.Scale(
                                extents,
                                new Vector3(x, y, z)));
                        if (viewport.z <= 0f)
                        {
                            continue;
                        }
                        minX = Mathf.Min(minX, viewport.x);
                        minY = Mathf.Min(minY, viewport.y);
                        maxX = Mathf.Max(maxX, viewport.x);
                        maxY = Mathf.Max(maxY, viewport.y);
                    }
                }
            }

            if (
                float.IsInfinity(minX)
                || float.IsInfinity(minY)
                || float.IsInfinity(maxX)
                || float.IsInfinity(maxY)
            )
            {
                return false;
            }
            viewportBounds = Rect.MinMaxRect(minX, minY, maxX, maxY);
            return true;
        }

        public bool TryGetPackViewportBounds(out Rect viewportBounds)
        {
            viewportBounds = default;
            if (
                captureCamera == null
                || packBodyRenderer == null
                || tearStripRenderer == null
                || !packBodyRenderer.enabled
            )
            {
                return false;
            }

            Bounds worldBounds = packBodyRenderer.bounds;
            if (tearStripRenderer.enabled)
            {
                worldBounds.Encapsulate(tearStripRenderer.bounds);
            }
            Vector3 center = worldBounds.center;
            Vector3 extents = worldBounds.extents;
            float minX = float.PositiveInfinity;
            float minY = float.PositiveInfinity;
            float maxX = float.NegativeInfinity;
            float maxY = float.NegativeInfinity;
            for (int x = -1; x <= 1; x += 2)
            {
                for (int y = -1; y <= 1; y += 2)
                {
                    for (int z = -1; z <= 1; z += 2)
                    {
                        Vector3 viewport = captureCamera.WorldToViewportPoint(
                            center + Vector3.Scale(
                                extents,
                                new Vector3(x, y, z)));
                        if (viewport.z <= 0f)
                        {
                            continue;
                        }
                        minX = Mathf.Min(minX, viewport.x);
                        minY = Mathf.Min(minY, viewport.y);
                        maxX = Mathf.Max(maxX, viewport.x);
                        maxY = Mathf.Max(maxY, viewport.y);
                    }
                }
            }
            if (
                float.IsInfinity(minX)
                || float.IsInfinity(minY)
                || float.IsInfinity(maxX)
                || float.IsInfinity(maxY)
            )
            {
                return false;
            }
            viewportBounds = Rect.MinMaxRect(minX, minY, maxX, maxY);
            return true;
        }

        public float MeasureFreedTailCurvature(float tearProgress)
        {
            float progress = Mathf.Clamp01(tearProgress);
            if (progress <= 0.001f)
            {
                return 0f;
            }
            float front = Mathf.Lerp(PackHalfWidth, -PackHalfWidth, progress);
            Vector3 a = EvaluateTailPoint(front, 0.25f, progress);
            Vector3 b = EvaluateTailPoint(front, 0.50f, progress);
            Vector3 c = EvaluateTailPoint(front, 0.75f, progress);
            return (a - 2f * b + c).magnitude;
        }

        private void Initialize()
        {
            if (initialized || !HasRequiredBindings)
            {
                return;
            }

            GenerateTearOffsets();
            cameraBasePosition = captureCamera.transform.position;
            cameraBaseRotation = captureCamera.transform.rotation;
            cameraBaseFov = captureCamera.fieldOfView;
            packBaseScale = packRoot.localScale;
            caseBasePosition = caseMotionRoot.localPosition;
            caseBaseRotation = caseMotionRoot.localRotation;
            caseBaseScale = caseMotionRoot.localScale;
            environmentProperties = new MaterialPropertyBlock();
            packProperties = new MaterialPropertyBlock();
            sourceEffectProperties = new MaterialPropertyBlock();
            caseProperties = new MaterialPropertyBlock();
            BuildBodyMesh();
            BuildStripMesh();
            BuildCavityMesh();
            BuildContactShadowMesh();
            BuildSpecularMesh();
            ApplyEnvironment();
            caseMotionRoot.gameObject.SetActive(true);
            casePresentation.SetTimeForPreview(
                casePresentation.RevealProfile.TotalDurationSeconds);
            caseRenderers = casePresentation
                .GetComponentsInChildren<Renderer>(true)
                .Where(renderer => renderer != null)
                .ToArray();
            caseTextRenderers = casePresentation
                .GetComponentsInChildren<TextMesh>(true)
                .Select(label => label.GetComponent<Renderer>())
                .Where(renderer => renderer != null)
                .ToArray();
            caseRendererEntityIds = caseRenderers
                .Select(renderer => renderer.GetEntityId())
                .ToArray();
            StopSourceEffects();
            initialized = true;
        }

        private void ApplyEnvironment()
        {
            environmentRenderer.GetPropertyBlock(environmentProperties);
            environmentProperties.SetTexture(BaseMapId, environmentTexture);
            environmentProperties.SetColor(
                BaseColorId,
                new Color(0.72f, 0.74f, 0.72f, 1f));
            environmentProperties.SetFloat(SaturationId, 0.44f);
            environmentProperties.SetFloat(OpacityId, 1f);
            environmentRenderer.SetPropertyBlock(environmentProperties);
        }

        private void ApplyPack(PackOpeningGate04R011Sample sample)
        {
            bool visible = sample.PackRetreat < 0.999f;
            packBodyRenderer.enabled = visible;
            tearStripRenderer.enabled = visible;
            cavityRenderer.enabled =
                visible
                && sample.ApertureProgress > 0.006f
                && sample.PackRetreat < 0.58f;
            contactShadowRenderer.enabled =
                visible
                && sample.TearProgress > 0.008f
                && sample.TearProgress < 0.995f
                && sample.PackRetreat < 0.20f;
            specularRenderer.enabled =
                visible
                && sample.TearProgress > 0.10f
                && sample.PackRetreat < 0.34f;
            packBodyRenderer.GetPropertyBlock(packProperties);
            packProperties.SetFloat(DissolveId, sample.PackDissolve);
            packBodyRenderer.SetPropertyBlock(packProperties);
            packRoot.localScale = Vector3.Scale(
                packBaseScale,
                new Vector3(
                    1f + sample.PackCompression * 0.20f,
                    1f - sample.PackCompression,
                    1f));

            TearFrontXLocal = Mathf.Lerp(
                PackHalfWidth,
                -PackHalfWidth,
                sample.TearProgress);
            UpdateBodyMesh(sample);
            UpdateStripMesh(sample);
            UpdateCavityMesh(sample);
            UpdateContactShadow(sample);
            UpdateSpecularHighlight(sample);
        }

        private void ApplyCase(PackOpeningGate04R011Sample sample)
        {
            Vector3 concealed = caseBasePosition;
            Vector3 hero = new Vector3(
                caseBasePosition.x,
                caseBasePosition.y - 0.017f,
                caseBasePosition.z - 0.300f);
            Vector3 position = Vector3.Lerp(
                concealed,
                hero,
                sample.CaseTravel);
            position.y += sample.CaseSettleOffset;
            caseMotionRoot.localPosition = position;
            caseMotionRoot.localRotation = caseBaseRotation
                * Quaternion.Euler(0f, sample.CaseRotationDegrees, 0f);
            caseMotionRoot.localScale = caseBaseScale;
            bool labelsVisible = sample.PackRetreat >= 0.72f;
            for (int index = 0; index < caseTextRenderers.Length; index++)
            {
                if (caseTextRenderers[index] != null)
                {
                    caseTextRenderers[index].enabled = labelsVisible;
                }
            }

            float sheenStrength = sample.CaseSheen > 0f
                ? Mathf.Sin(sample.CaseSheen * Mathf.PI) * 0.16f
                : 0f;
            for (int index = 0; index < casePresentation.EffectRenderers.Count; index++)
            {
                Renderer renderer = casePresentation.EffectRenderers[index];
                if (renderer == null)
                {
                    continue;
                }
                renderer.GetPropertyBlock(caseProperties);
                caseProperties.SetFloat(
                    SheenCenterId,
                    Mathf.Lerp(-0.12f, 1.12f, sample.CaseSheen));
                caseProperties.SetFloat(SheenWidthId, 0.065f);
                caseProperties.SetFloat(SheenStrengthId, sheenStrength);
                caseProperties.SetFloat(SheenFalloffId, 0.32f);
                renderer.SetPropertyBlock(caseProperties);
            }
        }

        private void ApplyImpact(PackOpeningGate04R011Sample sample)
        {
            SimulateSourceSystem(
                sourceActivationGlow,
                sample.ActivationEnabled,
                sample.ActivationAge,
                1.23f);
            SimulateSourceSystem(
                sourceLightningStrips,
                sample.LightningEnabled,
                sample.LightningAge,
                1.46f);
            SimulateSourceSystem(
                sourceLightningSparks,
                sample.LightningEnabled,
                sample.LightningAge,
                1.46f);
            SimulateSourceSystem(
                sourceExplosionDust,
                sample.ExplosionEnabled,
                sample.ExplosionAge,
                1.20f);
            SimulateSourceSystem(
                sourceExplosionFlares,
                sample.ExplosionEnabled,
                sample.ExplosionAge,
                1.20f);
        }

        private void ApplyCamera(PackOpeningGate04R011Sample sample)
        {
            captureCamera.transform.position =
                cameraBasePosition
                + cameraBaseRotation * Vector3.forward * sample.CameraPush
                + cameraBaseRotation * new Vector3(
                    sample.CameraKick.x,
                    sample.CameraKick.y,
                    0f);
            captureCamera.transform.rotation = cameraBaseRotation;
            captureCamera.fieldOfView = cameraBaseFov
                - sample.CameraPush * 5.5f
                + Mathf.Abs(sample.CameraKick.x) * 18f;
        }

        private void GenerateTearOffsets()
        {
            const uint seed = 0x6A09E667u;
            uint state = seed;
            var raw = new float[tearOffsets.Length];
            for (int index = 0; index < raw.Length; index++)
            {
                state = state * 1664525u + 1013904223u;
                float unit = ((state >> 8) & 0x00FFFFFFu) / 16777215f;
                raw[index] = unit * 2f - 1f;
            }
            for (int index = 0; index < tearOffsets.Length; index++)
            {
                float previous = raw[Mathf.Max(0, index - 1)];
                float current = raw[index];
                float next = raw[Mathf.Min(raw.Length - 1, index + 1)];
                float lowFrequency = Mathf.Sin(index * 0.73f + 0.45f) * 0.38f;
                tearOffsets[index] = Mathf.Clamp(
                    (previous + current * 2f + next) * 0.125f
                    + lowFrequency,
                    -1f,
                    1f) * MaximumTearAmplitude;
            }
            tearOffsets[0] *= 0.45f;
            tearOffsets[tearOffsets.Length - 1] *= 0.45f;
        }

        private void BuildBodyMesh()
        {
            bodyMesh = new Mesh { name = "Gate04R011PhysicalPackOccluder" };
            bodyMesh.MarkDynamic();
            bodyMesh.vertices = bodyVertices;
            bodyMesh.uv = bodyUvs;
            bodyMesh.triangles = Array.Empty<int>();
            packBodyMeshFilter.sharedMesh = bodyMesh;
        }

        private void UpdateBodyMesh(PackOpeningGate04R011Sample sample)
        {
            bodyTriangles.Clear();
            for (int column = 0; column <= StripSegments; column++)
            {
                float column01 = column / (float)StripSegments;
                float x = Mathf.Lerp(-PackHalfWidth, PackHalfWidth, column01);
                bool released =
                    sample.TearProgress >= 0.999f
                    || x > TearFrontXLocal;
                float release = released
                    ? Mathf.Clamp01(
                        (x - TearFrontXLocal)
                        / Mathf.Max(0.0001f, PackHalfWidth - TearFrontXLocal))
                    : 0f;
                float openedBehindFront = released
                    ? Smooth01(Mathf.InverseLerp(0f, 0.16f, release))
                    : 0f;
                float edgeDepth =
                    ApertureDepth
                    * sample.ApertureProgress
                    * openedBehindFront;
                float originalTop = TearSeamY + tearOffsets[column];
                for (int row = 0; row <= BodyRows; row++)
                {
                    float row01 = row / (float)BodyRows;
                    float topInfluence = Mathf.Pow(row01, 4f);
                    float y = Mathf.Lerp(PackBottomY, originalTop, row01)
                        - edgeDepth * topInfluence;
                    float retreatThreshold =
                        (1f - row01) * 0.92f;
                    float localRetreat = sample.PackRetreat <= 0f
                        ? 0f
                        : Smooth01(Mathf.InverseLerp(
                            retreatThreshold - 0.07f,
                            retreatThreshold + 0.19f,
                            sample.PackRetreat));
                    float outward = Mathf.Sign(Mathf.Abs(x) < 0.0001f ? 1f : x);
                    int index = BodyIndex(column, row);
                    bodyVertices[index] = new Vector3(
                        x + outward * localRetreat * (0.028f + 0.065f * row01),
                        y - localRetreat * (0.035f + 0.105f * row01),
                        PackPlaneZ - localRetreat * (0.012f + 0.016f * row01));
                    bodyUvs[index] = new Vector2(
                        column01,
                        Mathf.Clamp01(
                            Mathf.Lerp(
                                0f,
                                originalTop / PackHeight + 0.5f,
                                row01)));
                }
            }

            for (int column = 0; column < StripSegments; column++)
            {
                for (int row = 0; row < BodyRows; row++)
                {
                    int lower = BodyIndex(column, row);
                    int upper = BodyIndex(column, row + 1);
                    int nextLower = BodyIndex(column + 1, row);
                    int nextUpper = BodyIndex(column + 1, row + 1);
                    bodyTriangles.Add(lower);
                    bodyTriangles.Add(upper);
                    bodyTriangles.Add(nextLower);
                    bodyTriangles.Add(nextLower);
                    bodyTriangles.Add(upper);
                    bodyTriangles.Add(nextUpper);
                }
            }

            bodyMesh.Clear(false);
            bodyMesh.vertices = bodyVertices;
            bodyMesh.uv = bodyUvs;
            bodyMesh.SetTriangles(bodyTriangles, 0);
            bodyMesh.RecalculateNormals();
            bodyMesh.RecalculateBounds();
        }

        private void BuildStripMesh()
        {
            stripMesh = new Mesh
            {
                name = "Gate04R011SubdividedDeformableFoilStrip",
                subMeshCount = 3
            };
            stripMesh.MarkDynamic();
            int frontTriangle = 0;
            int backTriangle = 0;
            int edgeTriangle = 0;
            for (int column = 0; column < StripSegments; column++)
            {
                for (int row = 0; row < StripRows; row++)
                {
                    int frontLower = StripIndex(column, row, 0);
                    int frontUpper = StripIndex(column, row + 1, 0);
                    int frontNextLower = StripIndex(column + 1, row, 0);
                    int frontNextUpper = StripIndex(column + 1, row + 1, 0);
                    stripTriangles[0][frontTriangle++] = frontLower;
                    stripTriangles[0][frontTriangle++] = frontUpper;
                    stripTriangles[0][frontTriangle++] = frontNextLower;
                    stripTriangles[0][frontTriangle++] = frontNextLower;
                    stripTriangles[0][frontTriangle++] = frontUpper;
                    stripTriangles[0][frontTriangle++] = frontNextUpper;

                    int backLower = StripIndex(column, row, 1);
                    int backUpper = StripIndex(column, row + 1, 1);
                    int backNextLower = StripIndex(column + 1, row, 1);
                    int backNextUpper = StripIndex(column + 1, row + 1, 1);
                    stripTriangles[1][backTriangle++] = backLower;
                    stripTriangles[1][backTriangle++] = backNextLower;
                    stripTriangles[1][backTriangle++] = backUpper;
                    stripTriangles[1][backTriangle++] = backNextLower;
                    stripTriangles[1][backTriangle++] = backNextUpper;
                    stripTriangles[1][backTriangle++] = backUpper;
                }

                AddStripEdgeQuad(
                    column,
                    column + 1,
                    0,
                    ref edgeTriangle);
                AddStripEdgeQuad(
                    column + 1,
                    column,
                    StripRows,
                    ref edgeTriangle);
            }
            for (int row = 0; row < StripRows; row++)
            {
                AddStripCapQuad(0, row + 1, row, ref edgeTriangle);
                AddStripCapQuad(
                    StripSegments,
                    row,
                    row + 1,
                    ref edgeTriangle);
            }

            stripMesh.vertices = stripVertices;
            stripMesh.uv = stripUvs;
            stripMesh.colors = stripColors;
            stripMesh.SetTriangles(stripTriangles[0], 0);
            stripMesh.SetTriangles(stripTriangles[1], 1);
            stripMesh.SetTriangles(stripTriangles[2], 2);
            tearStripMeshFilter.sharedMesh = stripMesh;
        }

        private void AddStripEdgeQuad(
            int firstColumn,
            int secondColumn,
            int row,
            ref int triangle)
        {
            int firstFront = StripIndex(firstColumn, row, 0);
            int firstBack = StripIndex(firstColumn, row, 1);
            int secondFront = StripIndex(secondColumn, row, 0);
            int secondBack = StripIndex(secondColumn, row, 1);
            stripTriangles[2][triangle++] = firstFront;
            stripTriangles[2][triangle++] = secondFront;
            stripTriangles[2][triangle++] = firstBack;
            stripTriangles[2][triangle++] = firstBack;
            stripTriangles[2][triangle++] = secondFront;
            stripTriangles[2][triangle++] = secondBack;
        }

        private void AddStripCapQuad(
            int column,
            int firstRow,
            int secondRow,
            ref int triangle)
        {
            int firstFront = StripIndex(column, firstRow, 0);
            int firstBack = StripIndex(column, firstRow, 1);
            int secondFront = StripIndex(column, secondRow, 0);
            int secondBack = StripIndex(column, secondRow, 1);
            stripTriangles[2][triangle++] = firstFront;
            stripTriangles[2][triangle++] = secondFront;
            stripTriangles[2][triangle++] = firstBack;
            stripTriangles[2][triangle++] = firstBack;
            stripTriangles[2][triangle++] = secondFront;
            stripTriangles[2][triangle++] = secondBack;
        }

        private void UpdateStripMesh(PackOpeningGate04R011Sample sample)
        {
            maximumAheadOfFrontSeparation = 0f;
            for (int column = 0; column <= StripSegments; column++)
            {
                float column01 = column / (float)StripSegments;
                float originalX = Mathf.Lerp(
                    -PackHalfWidth,
                    PackHalfWidth,
                    column01);
                bool released =
                    sample.TearProgress > 0.0001f
                    && (
                        sample.TearProgress >= 0.999f
                        || originalX > TearFrontXLocal
                    );
                Vector3 center;
                Vector3 tangent;
                Vector3 widthDirection;
                Vector3 surfaceNormal;
                if (!released && sample.TearProgress < 0.999f)
                {
                    center = new Vector3(
                        originalX,
                        TearSeamY + tearOffsets[column] + StripHeight * 0.5f,
                        PackPlaneZ);
                    tangent = Vector3.right;
                    widthDirection = Vector3.up;
                    surfaceNormal = Vector3.forward;
                }
                else
                {
                    float tail = Mathf.Clamp01(
                        (originalX - TearFrontXLocal)
                        / Mathf.Max(0.0001f, PackHalfWidth - TearFrontXLocal));
                    EvaluateTailFrame(
                        TearFrontXLocal,
                        tail,
                        sample.TearProgress,
                        out center,
                        out tangent,
                        out widthDirection,
                        out surfaceNormal);
                    float retreat = sample.PackRetreat;
                    center += new Vector3(
                        retreat * (0.115f + 0.145f * tail),
                        retreat * (0.160f + 0.180f * tail),
                        -retreat * (0.018f + 0.030f * tail));
                }

                for (int row = 0; row <= StripRows; row++)
                {
                    float row01 = row / (float)StripRows;
                    float widthOffset = (row01 - 0.5f) * StripHeight;
                    Vector3 centerAtRow = center + widthDirection * widthOffset;
                    int frontIndex = StripIndex(column, row, 0);
                    int backIndex = StripIndex(column, row, 1);
                    stripVertices[frontIndex] =
                        centerAtRow - surfaceNormal * (StripThickness * 0.5f);
                    stripVertices[backIndex] =
                        centerAtRow + surfaceNormal * (StripThickness * 0.5f);
                    Vector2 uv = new Vector2(
                        column01,
                        Mathf.Lerp(FlapUvMin, FlapUvMax, row01));
                    stripUvs[frontIndex] = uv;
                    stripUvs[backIndex] = uv;
                    stripColors[frontIndex] = Color.white;
                    stripColors[backIndex] = Color.white;
                }

                if (!released)
                {
                    Vector3 stripBottom =
                        (stripVertices[StripIndex(column, 0, 0)]
                        + stripVertices[StripIndex(column, 0, 1)]) * 0.5f;
                    Vector3 bodyTop = bodyVertices[BodyIndex(column, BodyRows)];
                    maximumAheadOfFrontSeparation = Mathf.Max(
                        maximumAheadOfFrontSeparation,
                        Vector3.Distance(stripBottom, bodyTop));
                }
            }

            stripMesh.vertices = stripVertices;
            stripMesh.uv = stripUvs;
            stripMesh.colors = stripColors;
            stripMesh.RecalculateNormals();
            stripMesh.RecalculateBounds();
        }

        private void EvaluateTailFrame(
            float front,
            float tail,
            float tearProgress,
            out Vector3 center,
            out Vector3 tangent,
            out Vector3 widthDirection,
            out Vector3 surfaceNormal)
        {
            float frontOffset = TearOffsetAtX(front);
            float freeLength = Mathf.Max(0.001f, PackHalfWidth - front);
            Vector3 p0 = new Vector3(
                front,
                TearSeamY + frontOffset + StripHeight * 0.5f,
                PackPlaneZ);
            Vector3 p1 = p0 + new Vector3(
                Mathf.Min(0.052f, freeLength * 0.24f),
                0.010f + tearProgress * 0.012f,
                -0.006f);
            Vector3 p2 = new Vector3(
                PackHalfWidth + 0.016f + tearProgress * 0.007f,
                TearSeamY + StripHeight * 0.5f
                    + 0.050f + tearProgress * 0.040f,
                -0.023f - tearProgress * 0.022f);
            Vector3 p3 = new Vector3(
                PackHalfWidth - 0.028f - tearProgress * 0.078f,
                TearSeamY + StripHeight * 0.5f
                    + 0.056f + tearProgress * 0.025f,
                -0.014f - tearProgress * 0.043f);
            center = CubicBezier(p0, p1, p2, p3, tail);
            tangent = CubicBezierTangent(p0, p1, p2, p3, tail).normalized;
            float twistDegrees = Smooth01(tail)
                * Mathf.Lerp(56f, 168f, tearProgress);
            widthDirection =
                Quaternion.AngleAxis(twistDegrees, tangent) * Vector3.up;
            widthDirection = Vector3.ProjectOnPlane(widthDirection, tangent)
                .normalized;
            if (widthDirection.sqrMagnitude < 0.5f)
            {
                widthDirection = Vector3.up;
            }
            surfaceNormal = Vector3.Cross(tangent, widthDirection).normalized;
            if (surfaceNormal.sqrMagnitude < 0.5f)
            {
                surfaceNormal = Vector3.forward;
            }
        }

        private Vector3 EvaluateTailPoint(
            float front,
            float tail,
            float tearProgress)
        {
            EvaluateTailFrame(
                front,
                tail,
                tearProgress,
                out Vector3 center,
                out _,
                out _,
                out _);
            return center;
        }

        private void BuildCavityMesh()
        {
            cavityMesh = new Mesh
            {
                name = "Gate04R011ShapedParallaxCavity"
            };
            cavityMesh.MarkDynamic();
            cavityMesh.vertices = cavityVertices;
            cavityMesh.uv = cavityUvs;
            cavityMesh.triangles = Array.Empty<int>();
            cavityMeshFilter.sharedMesh = cavityMesh;
        }

        private void UpdateCavityMesh(PackOpeningGate04R011Sample sample)
        {
            cavityTriangles.Clear();
            for (int column = 0; column <= StripSegments; column++)
            {
                float column01 = column / (float)StripSegments;
                float x = Mathf.Lerp(-PackHalfWidth, PackHalfWidth, column01);
                bool released =
                    sample.TearProgress >= 0.999f
                    || x > TearFrontXLocal;
                float release = released
                    ? Mathf.Clamp01(
                        (x - TearFrontXLocal)
                        / Mathf.Max(0.0001f, PackHalfWidth - TearFrontXLocal))
                    : 0f;
                float openedBehindFront = released
                    ? Smooth01(Mathf.InverseLerp(0f, 0.16f, release))
                    : 0f;
                float bodyTop = TearSeamY
                    + tearOffsets[column]
                    - ApertureDepth
                        * sample.ApertureProgress
                        * openedBehindFront;
                float fold = 0.0016f * Mathf.Sin(column * 1.19f + 0.7f);
                int index = column * 4;
                cavityVertices[index] = new Vector3(
                    x,
                    bodyTop + 0.0012f,
                    PackPlaneZ + 0.0006f);
                cavityVertices[index + 1] = new Vector3(
                    x,
                    bodyTop + 0.006f + fold,
                    PackPlaneZ + 0.020f);
                cavityVertices[index + 2] = new Vector3(
                    x,
                    bodyTop - 0.013f + fold * 0.55f,
                    PackPlaneZ + 0.030f);
                cavityVertices[index + 3] = new Vector3(
                    x,
                    bodyTop - 0.004f,
                    PackPlaneZ + 0.0022f);
                cavityUvs[index] = new Vector2(column01, 1f);
                cavityUvs[index + 1] = new Vector2(column01, 0.72f);
                cavityUvs[index + 2] = new Vector2(column01, 0f);
                cavityUvs[index + 3] = new Vector2(column01, 0.28f);
            }

            for (int column = 0; column < StripSegments; column++)
            {
                float midpoint = Mathf.Lerp(
                    -PackHalfWidth,
                    PackHalfWidth,
                    (column + 0.5f) / StripSegments);
                if (
                    sample.TearProgress < 0.999f
                    && midpoint <= TearFrontXLocal
                )
                {
                    continue;
                }
                int current = column * 4;
                int next = (column + 1) * 4;
                for (int row = 0; row < 3; row++)
                {
                    cavityTriangles.Add(current + row);
                    cavityTriangles.Add(next + row);
                    cavityTriangles.Add(current + row + 1);
                    cavityTriangles.Add(current + row + 1);
                    cavityTriangles.Add(next + row);
                    cavityTriangles.Add(next + row + 1);
                }
            }

            cavityMesh.Clear(false);
            cavityMesh.vertices = cavityVertices;
            cavityMesh.uv = cavityUvs;
            cavityMesh.SetTriangles(cavityTriangles, 0);
            cavityMesh.RecalculateNormals();
            cavityMesh.RecalculateBounds();
        }

        private void BuildContactShadowMesh()
        {
            contactShadowMesh = new Mesh
            {
                name = "Gate04R011RestrainedContactShadow"
            };
            contactShadowMesh.vertices = contactShadowVertices;
            contactShadowMesh.uv = contactShadowUvs;
            contactShadowMesh.triangles = contactShadowTriangles;
            contactShadowMeshFilter.sharedMesh = contactShadowMesh;
        }

        private void UpdateContactShadow(PackOpeningGate04R011Sample sample)
        {
            float front = TearFrontXLocal;
            float x0 = Mathf.Max(-PackHalfWidth, front - 0.012f);
            float x1 = Mathf.Min(PackHalfWidth, front + 0.038f);
            float y = TearSeamY + TearOffsetAtX(front) - 0.0045f
                - sample.ApertureProgress * 0.010f;
            contactShadowVertices[0] = new Vector3(x0, y - 0.004f, -0.0011f);
            contactShadowVertices[1] = new Vector3(x0, y + 0.003f, -0.0011f);
            contactShadowVertices[2] = new Vector3(x1, y - 0.005f, -0.0011f);
            contactShadowVertices[3] = new Vector3(x1, y + 0.002f, -0.0011f);
            contactShadowMesh.vertices = contactShadowVertices;
            contactShadowMesh.RecalculateBounds();
        }

        private void BuildSpecularMesh()
        {
            specularMesh = new Mesh
            {
                name = "Gate04R011MovingNarrowFoilSpecular"
            };
            specularMesh.vertices = specularVertices;
            specularMesh.uv = specularUvs;
            specularMesh.triangles = specularTriangles;
            specularMeshFilter.sharedMesh = specularMesh;
        }

        private void UpdateSpecularHighlight(PackOpeningGate04R011Sample sample)
        {
            float center = Mathf.Lerp(0.24f, 0.70f, sample.TearProgress);
            float s0 = Mathf.Clamp01(center - 0.090f);
            float s1 = Mathf.Clamp01(center + 0.090f);
            EvaluateTailFrame(
                TearFrontXLocal,
                s0,
                sample.TearProgress,
                out Vector3 center0,
                out _,
                out Vector3 width0,
                out Vector3 normal0);
            EvaluateTailFrame(
                TearFrontXLocal,
                s1,
                sample.TearProgress,
                out Vector3 center1,
                out _,
                out Vector3 width1,
                out Vector3 normal1);
            float halfWidth = StripHeight * 0.060f;
            specularVertices[0] =
                center0 - width0 * halfWidth - normal0 * 0.00055f;
            specularVertices[1] =
                center0 + width0 * halfWidth - normal0 * 0.00055f;
            specularVertices[2] =
                center1 - width1 * halfWidth - normal1 * 0.00055f;
            specularVertices[3] =
                center1 + width1 * halfWidth - normal1 * 0.00055f;
            specularMesh.vertices = specularVertices;
            specularMesh.RecalculateNormals();
            specularMesh.RecalculateBounds();
        }

        private float TearOffsetAtX(float x)
        {
            float normalized = Mathf.InverseLerp(
                -PackHalfWidth,
                PackHalfWidth,
                x);
            float scaled = normalized * StripSegments;
            int lower = Mathf.Clamp(Mathf.FloorToInt(scaled), 0, StripSegments);
            int upper = Mathf.Min(StripSegments, lower + 1);
            return Mathf.Lerp(tearOffsets[lower], tearOffsets[upper], scaled - lower);
        }

        private string BuildStateFingerprint()
        {
            if (!initialized)
            {
                return string.Empty;
            }
            var builder = new StringBuilder(32768);
            AppendVector(builder, cameraBasePosition);
            AppendVector(builder, captureCamera.transform.position);
            AppendQuaternion(builder, captureCamera.transform.rotation);
            AppendFloat(builder, captureCamera.fieldOfView);
            AppendVector(builder, packRoot.localScale);
            AppendVector(builder, caseMotionRoot.localPosition);
            AppendQuaternion(builder, caseMotionRoot.localRotation);
            AppendVector(builder, caseMotionRoot.localScale);
            builder.Append(packBodyRenderer.enabled ? '1' : '0');
            builder.Append(tearStripRenderer.enabled ? '1' : '0');
            builder.Append(cavityRenderer.enabled ? '1' : '0');
            builder.Append(contactShadowRenderer.enabled ? '1' : '0');
            builder.Append(specularRenderer.enabled ? '1' : '0');
            foreach (ParticleSystem system in SourceEffectSystems)
            {
                builder.Append(system != null ? system.particleCount : -1)
                    .Append('|');
            }
            for (int index = 0; index < caseTextRenderers.Length; index++)
            {
                builder.Append(
                    caseTextRenderers[index] != null
                    && caseTextRenderers[index].enabled
                        ? '1'
                        : '0');
            }
            builder.Append('|')
                .Append((int)packBodyRenderer.shadowCastingMode)
                .Append('|')
                .Append((int)tearStripRenderer.shadowCastingMode)
                .Append('|')
                .Append((int)cavityRenderer.shadowCastingMode);
            builder.Append('|').Append(bodyMesh.GetIndexCount(0));
            builder.Append('|').Append(cavityMesh.GetIndexCount(0));
            AppendRendererProperties(
                builder,
                environmentRenderer,
                includeTexture: true);
            AppendRendererProperties(
                builder,
                packBodyRenderer,
                includeTexture: true);
            for (int index = 0; index < casePresentation.EffectRenderers.Count; index++)
            {
                AppendRendererProperties(
                    builder,
                    casePresentation.EffectRenderers[index],
                    includeTexture: false);
            }
            AppendVertices(builder, bodyVertices);
            AppendVertices(builder, stripVertices);
            AppendVertices(builder, cavityVertices);
            AppendVertices(builder, contactShadowVertices);
            AppendVertices(builder, specularVertices);
            AppendFloat(builder, maximumAheadOfFrontSeparation);
            return builder.ToString();
        }

        private static void AppendRendererProperties(
            StringBuilder builder,
            Renderer renderer,
            bool includeTexture)
        {
            if (renderer == null)
            {
                builder.Append("null|");
                return;
            }
            var properties = new MaterialPropertyBlock();
            renderer.GetPropertyBlock(properties);
            AppendColor(builder, properties.GetColor(BaseColorId));
            AppendFloat(builder, properties.GetFloat(SaturationId));
            AppendFloat(builder, properties.GetFloat(OpacityId));
            AppendFloat(builder, properties.GetFloat(SheenCenterId));
            AppendFloat(builder, properties.GetFloat(SheenWidthId));
            AppendFloat(builder, properties.GetFloat(SheenStrengthId));
            AppendFloat(builder, properties.GetFloat(SheenFalloffId));
            AppendFloat(builder, properties.GetFloat(DissolveId));
            AppendFloat(builder, properties.GetFloat(ProgressId));
            AppendFloat(builder, properties.GetFloat(RevealId));
            AppendFloat(builder, properties.GetFloat(IntensityId));
            if (includeTexture)
            {
                Texture texture = properties.GetTexture(BaseMapId);
                builder.Append(texture != null ? texture.name : "null")
                    .Append('|');
            }
        }

        private static void AppendVertices(StringBuilder builder, Vector3[] vertices)
        {
            for (int index = 0; index < vertices.Length; index++)
            {
                AppendVector(builder, vertices[index]);
            }
        }

        private static void AppendVector(StringBuilder builder, Vector3 value)
        {
            AppendFloat(builder, value.x);
            AppendFloat(builder, value.y);
            AppendFloat(builder, value.z);
        }

        private static void AppendQuaternion(StringBuilder builder, Quaternion value)
        {
            AppendFloat(builder, value.x);
            AppendFloat(builder, value.y);
            AppendFloat(builder, value.z);
            AppendFloat(builder, value.w);
        }

        private static void AppendColor(StringBuilder builder, Color value)
        {
            AppendFloat(builder, value.r);
            AppendFloat(builder, value.g);
            AppendFloat(builder, value.b);
            AppendFloat(builder, value.a);
        }

        private static void AppendFloat(StringBuilder builder, float value)
        {
            builder.Append(value.ToString("R", CultureInfo.InvariantCulture))
                .Append('|');
        }

        private void SimulateSourceSystem(
            ParticleSystem system,
            bool enabled,
            float age,
            float authoredDuration)
        {
            if (system == null)
            {
                return;
            }
            system.Stop(
                true,
                ParticleSystemStopBehavior.StopEmittingAndClear);
            if (!enabled || age < 0f)
            {
                return;
            }
            float clampedAge = Mathf.Min(age, authoredDuration);
            system.Simulate(clampedAge, true, true, true);
            system.Pause(true);
            ParticleSystemRenderer renderer =
                system.GetComponent<ParticleSystemRenderer>();
            if (renderer == null)
            {
                return;
            }
            renderer.GetPropertyBlock(sourceEffectProperties);
            sourceEffectProperties.SetFloat(
                ProgressId,
                Mathf.Clamp01(clampedAge / authoredDuration));
            sourceEffectProperties.SetFloat(RevealId, 1f);
            sourceEffectProperties.SetFloat(IntensityId, 1f);
            renderer.SetPropertyBlock(sourceEffectProperties);
        }

        private void StopSourceEffects()
        {
            StopParticles(sourceActivationGlow);
            StopParticles(sourceLightningStrips);
            StopParticles(sourceLightningSparks);
            StopParticles(sourceExplosionDust);
            StopParticles(sourceExplosionFlares);
        }

        private static void StopParticles(ParticleSystem system)
        {
            if (system == null)
            {
                return;
            }
            system.Stop(
                true,
                ParticleSystemStopBehavior.StopEmittingAndClear);
        }

        private static Vector3 CubicBezier(
            Vector3 p0,
            Vector3 p1,
            Vector3 p2,
            Vector3 p3,
            float value)
        {
            float t = Mathf.Clamp01(value);
            float inverse = 1f - t;
            return inverse * inverse * inverse * p0
                + 3f * inverse * inverse * t * p1
                + 3f * inverse * t * t * p2
                + t * t * t * p3;
        }

        private static Vector3 CubicBezierTangent(
            Vector3 p0,
            Vector3 p1,
            Vector3 p2,
            Vector3 p3,
            float value)
        {
            float t = Mathf.Clamp01(value);
            float inverse = 1f - t;
            return 3f * inverse * inverse * (p1 - p0)
                + 6f * inverse * t * (p2 - p1)
                + 3f * t * t * (p3 - p2);
        }

        private static float Smooth01(float value)
        {
            float clamped = Mathf.Clamp01(value);
            return clamped * clamped * (3f - 2f * clamped);
        }

        private static float EaseOutQuart(float value)
        {
            float clamped = Mathf.Clamp01(value);
            return 1f - Mathf.Pow(1f - clamped, 4f);
        }

        private static int BodyIndex(int column, int row)
        {
            return column * (BodyRows + 1) + row;
        }

        private static int StripIndex(int column, int row, int side)
        {
            return (column * (StripRows + 1) + row) * 2 + side;
        }

        private static void DestroyOwned(UnityEngine.Object value)
        {
            if (value == null)
            {
                return;
            }
            if (Application.isPlaying)
            {
                Destroy(value);
            }
            else
            {
                DestroyImmediate(value);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using FidgetingApp.DisplayCase.MakeItShineCc0;
using UnityEngine;

namespace FidgetingApp.DisplayCase.Candidates
{
    public enum PackOpeningGate04R011Phase
    {
        Handoff,
        Anticipation,
        Resistance,
        Snap,
        Tear,
        SourceImpact,
        SourceReveal,
        Settled
    }

    public enum PackOpeningGate04R011Occlusion
    {
        Sealed,
        AperturePartial,
        CrossingOccluder,
        PackGone
    }

    public enum PackOpeningGate04R011SemanticEvent
    {
        TearResistance,
        TearSnap,
        Impact,
        CaseSettled
    }

    public readonly struct PackOpeningGate04R011Sample
    {
        public PackOpeningGate04R011Sample(
            PackOpeningGate04R011Phase phase,
            PackOpeningGate04R011Occlusion occlusion,
            float sourceTimeSeconds,
            float tearProgress,
            float apertureProgress,
            float packRetreat,
            float packDissolve,
            float caseTravel,
            float caseRotationDegrees,
            float caseSettleOffset,
            float activationAge,
            float lightningAge,
            float explosionAge,
            float caseSheen,
            float rarityReveal,
            float cameraPush,
            Vector2 cameraKick,
            float packCompression,
            bool activationEnabled,
            bool lightningEnabled,
            bool explosionEnabled,
            bool heroSilhouetteRequired)
        {
            Phase = phase;
            Occlusion = occlusion;
            SourceTimeSeconds = sourceTimeSeconds;
            TearProgress = tearProgress;
            ApertureProgress = apertureProgress;
            PackRetreat = packRetreat;
            PackDissolve = packDissolve;
            CaseTravel = caseTravel;
            CaseRotationDegrees = caseRotationDegrees;
            CaseSettleOffset = caseSettleOffset;
            ActivationAge = activationAge;
            LightningAge = lightningAge;
            ExplosionAge = explosionAge;
            CaseSheen = caseSheen;
            RarityReveal = rarityReveal;
            CameraPush = cameraPush;
            CameraKick = cameraKick;
            PackCompression = packCompression;
            ActivationEnabled = activationEnabled;
            LightningEnabled = lightningEnabled;
            ExplosionEnabled = explosionEnabled;
            HeroSilhouetteRequired = heroSilhouetteRequired;
        }

        public PackOpeningGate04R011Phase Phase { get; }
        public PackOpeningGate04R011Occlusion Occlusion { get; }
        public float SourceTimeSeconds { get; }
        public float TearProgress { get; }
        public float ApertureProgress { get; }
        public float PackRetreat { get; }
        public float PackDissolve { get; }
        public float CaseTravel { get; }
        public float CaseRotationDegrees { get; }
        public float CaseSettleOffset { get; }
        public float ActivationAge { get; }
        public float LightningAge { get; }
        public float ExplosionAge { get; }
        public float CaseSheen { get; }
        public float RarityReveal { get; }
        public float CameraPush { get; }
        public Vector2 CameraKick { get; }
        public float PackCompression { get; }
        public bool ActivationEnabled { get; }
        public bool LightningEnabled { get; }
        public bool ExplosionEnabled { get; }
        public bool HeroSilhouetteRequired { get; }
    }

    [CreateAssetMenu(
        fileName = "PackOpeningGate04R011Profile",
        menuName = "Fidgeting/Display Case/Candidates/Pack Opening Gate 04 R011")]
    public sealed class PackOpeningGate04R011Profile : ScriptableObject
    {
        public const float TotalSeconds = 3.45f;
        public const float HandoffEnd = 0.28f;
        public const float AnticipationEnd = 0.55f;
        public const float ResistanceEnd = 0.85f;
        public const float SnapEnd = 0.90f;
        public const float TearEnd = 1.60f;
        public const float ImpactStart = TearEnd;
        public const float ImpactEnd = 1.78f;
        public const float ActivationStart = AnticipationEnd;
        public const float LightningStart = 1.02f;
        public const float SourceExplosionStart = 5.8194770813f;
        public const float SourceProxyResultStart = 5.9179303646f;
        public const float SourceSolidPackOff = 5.9333767891f;
        public const float SourceRealResultStart = 6.711848f;
        public const float SourceProxyResultOff = 6.742770f;
        public const float SourceTimeOffset = SourceExplosionStart - ImpactStart;
        public const float TargetProxyResultStart =
            SourceProxyResultStart - SourceTimeOffset;
        public const float TargetSolidPackOff =
            SourceSolidPackOff - SourceTimeOffset;
        public const float TargetRealResultStart =
            SourceRealResultStart - SourceTimeOffset;
        public const float TargetProxyResultOff =
            SourceProxyResultOff - SourceTimeOffset;
        public const float CaseSettleEnd = 2.82f;
        public const float SheenStart = 2.72f;
        public const float SheenEnd = 3.08f;
        public const float SettledStart = 3.10f;
        public const float ImpactDuration = ImpactEnd - ImpactStart;
        public const float SnapDuration = SnapEnd - ResistanceEnd;
        public const float StandardStartRotationDegrees = -25f;
        public const float ReducedStartRotationDegrees = -10f;

        public PackOpeningGate04R011Sample Evaluate(
            float elapsedSeconds,
            bool reduceMotion = false)
        {
            float elapsed = Mathf.Clamp(elapsedSeconds, 0f, TotalSeconds);
            float resistance = Smooth01(
                Mathf.InverseLerp(AnticipationEnd, ResistanceEnd, elapsed));
            float snap = EaseOutQuart(
                Mathf.InverseLerp(ResistanceEnd, SnapEnd, elapsed));
            float progressive = EaseOutCubic(
                Mathf.InverseLerp(SnapEnd, TearEnd, elapsed));

            float tear;
            if (elapsed < AnticipationEnd)
            {
                tear = 0f;
            }
            else if (elapsed < ResistanceEnd)
            {
                tear = Mathf.Lerp(0f, 0.06f, resistance);
            }
            else if (elapsed < SnapEnd)
            {
                tear = Mathf.Lerp(0.06f, 0.20f, snap);
            }
            else
            {
                tear = Mathf.Lerp(0.20f, 1f, progressive);
            }
            tear = Mathf.Clamp01(tear);

            float sourceTime = elapsed + SourceTimeOffset;
            float discardTime = Mathf.InverseLerp(
                TargetSolidPackOff,
                TargetProxyResultOff,
                elapsed);
            float packDissolve = elapsed < TargetSolidPackOff
                ? 0f
                : MakeItShineCc0EffectCurves
                    .CreateDiscardDissolveCurve()
                    .Evaluate(discardTime);
            float packRetreat = Smooth01(discardTime);
            float aperture = Smooth01(Mathf.InverseLerp(0.025f, 0.92f, tear));
            float caseTravel = Smooth01(Mathf.InverseLerp(
                TargetProxyResultStart,
                TargetRealResultStart,
                elapsed));
            float settle = Smooth01(Mathf.InverseLerp(
                TargetProxyResultStart,
                CaseSettleEnd,
                elapsed));
            float startRotation = reduceMotion
                ? ReducedStartRotationDegrees
                : StandardStartRotationDegrees;
            float caseRotation = Mathf.Lerp(startRotation, 0f, settle);
            float settleOffset = elapsed >= TargetRealResultStart
                && elapsed <= CaseSettleEnd
                ? Mathf.Sin(
                    Mathf.InverseLerp(
                        TargetRealResultStart,
                        CaseSettleEnd,
                        elapsed) * Mathf.PI)
                    * (1f - Mathf.InverseLerp(
                        TargetRealResultStart,
                        CaseSettleEnd,
                        elapsed))
                    * (reduceMotion ? 0.0015f : 0.006f)
                : 0f;

            float activationAge = elapsed - ActivationStart;
            float lightningAge = elapsed - LightningStart;
            float explosionAge = elapsed - ImpactStart;
            float sheen = Mathf.InverseLerp(SheenStart, SheenEnd, elapsed);
            if (elapsed < SheenStart || elapsed > SheenEnd)
            {
                sheen = 0f;
            }
            float rarityReveal = Smooth01(Mathf.InverseLerp(
                TargetRealResultStart,
                CaseSettleEnd,
                elapsed));

            float pushIn = Smooth01(
                Mathf.InverseLerp(HandoffEnd, ResistanceEnd, elapsed));
            float pushRecovery = EaseOutCubic(
                Mathf.InverseLerp(ImpactStart, ImpactEnd, elapsed));
            float cameraPush = reduceMotion
                ? 0f
                : 0.022f * pushIn * (1f - pushRecovery);
            Vector2 cameraKick = Vector2.zero;
            if (
                !reduceMotion
                && elapsed >= ImpactStart
                && elapsed < ImpactStart + 0.08f
            )
            {
                float kickTime = (elapsed - ImpactStart) / 0.08f;
                float envelope = 1f - EaseOutCubic(kickTime);
                cameraKick = new Vector2(
                    Mathf.Sin(kickTime * Mathf.PI) * 0.0024f,
                    Mathf.Sin(kickTime * Mathf.PI * 2f) * 0.0012f)
                    * envelope;
            }

            float compression = elapsed >= HandoffEnd
                && elapsed <= SnapEnd
                ? Mathf.Sin(
                    Mathf.InverseLerp(
                        HandoffEnd,
                        SnapEnd,
                        elapsed) * Mathf.PI)
                    * (reduceMotion ? 0.004f : 0.018f)
                : 0f;

            return new PackOpeningGate04R011Sample(
                ResolvePhase(elapsed),
                ResolveOcclusion(tear, packRetreat),
                sourceTime,
                tear,
                aperture,
                packRetreat,
                packDissolve,
                caseTravel,
                caseRotation,
                settleOffset,
                activationAge,
                lightningAge,
                explosionAge,
                sheen,
                rarityReveal,
                cameraPush,
                cameraKick,
                compression,
                !reduceMotion && activationAge >= 0f && elapsed <= ImpactEnd,
                !reduceMotion && lightningAge >= 0f && elapsed <= 2.48f,
                !reduceMotion && explosionAge >= 0f && elapsed <= 2.72f,
                elapsed >= ImpactStart);
        }

        public PackOpeningGate04R011SemanticEvent[] ResolveSemanticEvents(
            float previousSeconds,
            float elapsedSeconds)
        {
            float previous = Mathf.Clamp(previousSeconds, 0f, TotalSeconds);
            float current = Mathf.Clamp(elapsedSeconds, 0f, TotalSeconds);
            if (current <= previous)
            {
                return Array.Empty<PackOpeningGate04R011SemanticEvent>();
            }

            var events = new List<PackOpeningGate04R011SemanticEvent>(4);
            AddCrossing(
                events,
                previous,
                current,
                AnticipationEnd,
                PackOpeningGate04R011SemanticEvent.TearResistance);
            AddCrossing(
                events,
                previous,
                current,
                ResistanceEnd,
                PackOpeningGate04R011SemanticEvent.TearSnap);
            AddCrossing(
                events,
                previous,
                current,
                ImpactStart,
                PackOpeningGate04R011SemanticEvent.Impact);
            AddCrossing(
                events,
                previous,
                current,
                CaseSettleEnd,
                PackOpeningGate04R011SemanticEvent.CaseSettled);
            return events.ToArray();
        }

        private static PackOpeningGate04R011Phase ResolvePhase(float elapsed)
        {
            if (elapsed < HandoffEnd) return PackOpeningGate04R011Phase.Handoff;
            if (elapsed < AnticipationEnd) return PackOpeningGate04R011Phase.Anticipation;
            if (elapsed < ResistanceEnd) return PackOpeningGate04R011Phase.Resistance;
            if (elapsed < SnapEnd) return PackOpeningGate04R011Phase.Snap;
            if (elapsed < TearEnd) return PackOpeningGate04R011Phase.Tear;
            if (elapsed < ImpactEnd) return PackOpeningGate04R011Phase.SourceImpact;
            if (elapsed < SettledStart) return PackOpeningGate04R011Phase.SourceReveal;
            return PackOpeningGate04R011Phase.Settled;
        }

        private static PackOpeningGate04R011Occlusion ResolveOcclusion(
            float tear,
            float packRetreat)
        {
            if (tear <= 0.001f)
            {
                return PackOpeningGate04R011Occlusion.Sealed;
            }
            if (packRetreat <= 0.001f)
            {
                return PackOpeningGate04R011Occlusion.AperturePartial;
            }
            return packRetreat < 0.999f
                ? PackOpeningGate04R011Occlusion.CrossingOccluder
                : PackOpeningGate04R011Occlusion.PackGone;
        }

        private static void AddCrossing(
            ICollection<PackOpeningGate04R011SemanticEvent> events,
            float previous,
            float current,
            float threshold,
            PackOpeningGate04R011SemanticEvent semanticEvent)
        {
            if (previous < threshold && current >= threshold)
            {
                events.Add(semanticEvent);
            }
        }

        private static float Smooth01(float value)
        {
            float clamped = Mathf.Clamp01(value);
            return clamped * clamped * (3f - 2f * clamped);
        }

        private static float EaseOutCubic(float value)
        {
            float clamped = Mathf.Clamp01(value);
            return 1f - Mathf.Pow(1f - clamped, 3f);
        }

        private static float EaseOutQuart(float value)
        {
            float clamped = Mathf.Clamp01(value);
            return 1f - Mathf.Pow(1f - clamped, 4f);
        }
    }
}

Shader "FidgetingApp/Candidates/MakeItShineCc0PackR011"
{
    Properties
    {
        [MainTexture] _BaseMap("Pack Artwork", 2D) = "white" {}
        [MainColor] _BaseColor("Pack Tint", Color) = (1, 1, 1, 1)
        _NoiseMap("CC0 Dissolve Mask", 2D) = "gray" {}
        _Dissolve("CC0 Discard Progress", Range(0, 1)) = 0
        _DissolveScale("Mask Scale", Range(0.5, 4)) = 1.6
        _EdgeWidth("Edge Width", Range(0.001, 0.2)) = 0.055
        _EdgeColor("Edge Color", Color) = (0.72, 0.88, 1, 1)
        _EdgeStrength("Edge Strength", Range(0, 2)) = 0.42
        _Cutoff("Alpha Cutoff", Range(0, 1)) = 0.018
    }

    SubShader
    {
        Tags
        {
            "RenderType" = "TransparentCutout"
            "Queue" = "AlphaTest"
            "RenderPipeline" = "UniversalPipeline"
        }

        Pass
        {
            Name "ForwardUnlit"
            Tags { "LightMode" = "UniversalForward" }
            Cull Off
            ZWrite On

            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            TEXTURE2D(_BaseMap);
            SAMPLER(sampler_BaseMap);
            TEXTURE2D(_NoiseMap);
            SAMPLER(sampler_NoiseMap);

            CBUFFER_START(UnityPerMaterial)
                float4 _BaseMap_ST;
                half4 _BaseColor;
                half4 _EdgeColor;
                half _Dissolve;
                half _DissolveScale;
                half _EdgeWidth;
                half _EdgeStrength;
                half _Cutoff;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
                half4 color : COLOR;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float2 uv : TEXCOORD0;
                half4 color : COLOR;
            };

            Varyings Vert(Attributes input)
            {
                Varyings output;
                output.positionCS = TransformObjectToHClip(input.positionOS.xyz);
                output.uv = TRANSFORM_TEX(input.uv, _BaseMap);
                output.color = input.color;
                return output;
            }

            half4 Frag(Varyings input) : SV_Target
            {
                half4 artwork = SAMPLE_TEXTURE2D(
                    _BaseMap,
                    sampler_BaseMap,
                    input.uv) * _BaseColor * input.color;
                float2 centeredUv = (input.uv - 0.5) * _DissolveScale + 0.5;
                half noise = SAMPLE_TEXTURE2D(
                    _NoiseMap,
                    sampler_NoiseMap,
                    centeredUv).r;
                half threshold = saturate(_Dissolve);
                half signedDistance = noise - threshold;
                clip(min(artwork.a - _Cutoff, signedDistance));
                half edge = 1.0h - smoothstep(0.0h, _EdgeWidth, signedDistance);
                half3 color = artwork.rgb + _EdgeColor.rgb * edge * _EdgeStrength;
                return half4(color, 1.0h);
            }
            ENDHLSL
        }
    }
}

Shader "FidgetingApp/Candidates/MakeItShineCc0PortR011"
{
    Properties
    {
        [MainTexture] _BaseMap("CC0 Flare", 2D) = "white" {}
        [MainColor] _BaseColor("Color", Color) = (1, 1, 1, 1)
        _Reveal("SG Lighting Strike Reveal", Range(0, 1)) = 1
        _Erode("SG Lighting Strike Erode", Range(0, 1)) = 0
        _Speed("SG Lighting Strike Speed", Float) = 0
        _Progress("Timeline Progress", Range(0, 1)) = 0
        _Intensity("Intensity", Range(0, 4)) = 1
    }

    SubShader
    {
        Tags
        {
            "RenderType" = "Transparent"
            "Queue" = "Transparent"
            "RenderPipeline" = "UniversalPipeline"
        }

        Pass
        {
            Name "ForwardAdditive"
            Tags { "LightMode" = "UniversalForward" }
            Cull Off
            ZWrite Off
            ZTest LEqual
            Blend SrcAlpha One

            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
            #include "Assets/_DisplayCase/Runtime/MakeItShineCc0Effects/MakeItShineCc0Masks.hlsl"

            TEXTURE2D(_BaseMap);
            SAMPLER(sampler_BaseMap);

            CBUFFER_START(UnityPerMaterial)
                float4 _BaseMap_ST;
                half4 _BaseColor;
                half _Reveal;
                half _Erode;
                half _Speed;
                half _Progress;
                half _Intensity;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
                half4 color : COLOR;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float2 uv : TEXCOORD0;
                half4 color : COLOR;
            };

            Varyings Vert(Attributes input)
            {
                Varyings output;
                output.positionCS = TransformObjectToHClip(input.positionOS.xyz);
                output.uv = TRANSFORM_TEX(input.uv, _BaseMap);
                output.uv.x = frac(output.uv.x + _Progress * _Speed);
                output.color = input.color;
                return output;
            }

            half4 Frag(Varyings input) : SV_Target
            {
                half4 flare = SAMPLE_TEXTURE2D(
                    _BaseMap,
                    sampler_BaseMap,
                    input.uv);
                half sourceMask = max(flare.r, flare.a);
                half reveal = FidgetingCc0RevealThreshold(
                    sourceMask,
                    _Reveal);
                half eroded = smoothstep(
                    _Erode,
                    min(1.0h, _Erode + 0.08h),
                    sourceMask * reveal);
                half4 color = flare * _BaseColor * input.color;
                color.rgb *= _Intensity * eroded;
                color.a *= eroded;
                clip(color.a - 0.001h);
                return color;
            }
            ENDHLSL
        }
    }
}

Shader "FidgetingApp/Candidates/OpeningAccentR011"
{
    Properties
    {
        [MainTexture] _BaseMap("Texture", 2D) = "white" {}
        [MainColor] _BaseColor("Color", Color) = (1, 1, 1, 1)
    }

    SubShader
    {
        Tags
        {
            "RenderType" = "Transparent"
            "Queue" = "Transparent"
            "RenderPipeline" = "UniversalPipeline"
        }

        Pass
        {
            Name "ForwardUnlit"
            Tags { "LightMode" = "UniversalForward" }
            Cull Off
            ZWrite Off
            Blend SrcAlpha OneMinusSrcAlpha

            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            TEXTURE2D(_BaseMap);
            SAMPLER(sampler_BaseMap);

            CBUFFER_START(UnityPerMaterial)
                float4 _BaseMap_ST;
                half4 _BaseColor;
            CBUFFER_END

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
                half4 color : COLOR;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float2 uv : TEXCOORD0;
                half4 color : COLOR;
            };

            Varyings Vert(Attributes input)
            {
                Varyings output;
                output.positionCS = TransformObjectToHClip(input.positionOS.xyz);
                output.uv = TRANSFORM_TEX(input.uv, _BaseMap);
                output.color = input.color;
                return output;
            }

            half4 Frag(Varyings input) : SV_Target
            {
                half4 sampled = SAMPLE_TEXTURE2D(
